function jx(string $f):array{$x=json_decode((string)@file_get_contents($f),true);return is_array($x)?$x:[];}
function sjx(string $f,array $x):bool{$l=fopen($f.'.lock','c');if(!$l||!flock($l,LOCK_EX))return false;try{$t=$f.'.tmp.'.bin2hex(random_bytes(3));$q=json_encode($x,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT);if($q===false||file_put_contents($t,$q,LOCK_EX)===false)return false;@chmod($t,0640);return rename($t,$f);}finally{flock($l,LOCK_UN);fclose($l);}}
function nx():string{return date('Y-m-d H:i:s');}
function tdx():string{return date('Y-m-d');}
function gx(string $u):never{header('Location: '.$u);exit;}
function flx(string $m,string $t='ok'):void{$_SESSION['fl']=[$m,$t];}
function normx(string $s):string{$s=trim(mb_strtolower($s,'UTF-8'));$s=str_replace(['ي','ك','ۀ','ة'],['ی','ک','ه','ه'],$s);return preg_replace('/\s+/u',' ',$s)??$s;}
function splitx(string $s):array{$p=preg_split('/[,،;\n]+/u',$s)?:[];return array_values(array_filter(array_map(fn($x)=>normx((string)$x),$p)));}
function cfgx():array{return array_merge(['daily_quota'=>20,'commission_percent'=>30,'urgent_commission_percent'=>40,'special_interested_commission'=>40,'unseen_reassign_hours'=>48,'sms_sender'=>'90008361','sms_manager_mobile'=>'09024342370','sms_api_endpoint'=>'https://edge.ippanel.com/v1/api/send','sms_enabled'=>true],jx(S));}
function branchx(string $id):?array{foreach(jx(B) as $x)if((string)($x['id']??'')===$id)return $x;return null;}
function leadx(string $id):?array{foreach(jx(L) as $x)if((string)($x['id']??'')===$id)return $x;return null;}
function quotax(array $b):int{$q=(int)($b['daily_quota']??0);if($q<=0)$q=(int)(cfgx()['daily_quota']??20);return max(1,min(100,$q));}
function currentx():array{return array_values(array_filter(jx(A),fn($a)=>($a['current']??true)!==false&&($a['status']??'new')!=='reassigned'));}
function todayx(string $bid):int{$n=0;foreach(currentx() as $a)if((string)($a['branch_id']??'')===$bid&&($a['date']??'')===tdx())$n++;return $n;}
function statsx(string $bid):array{$assigned=0;$handled=0;$won=0;foreach(jx(A) as $a){if((string)($a['branch_id']??'')!==$bid)continue;$st=(string)($a['status']??'new');if($st==='reassigned')continue;$assigned++;if($st!=='new'){$handled++;if($st==='won')$won++;}}$resp=$assigned?($handled/$assigned):0.0;$conv=$handled?($won/$handled):0.0;$score=$handled<5?50:(int)round(($conv*80)+($resp*20));return ['score'=>max(1,min(100,$score)),'handled'=>$handled,'won'=>$won];}
function areaExactx(array $lead,array $b):bool{$lc=normx((string)($lead['city']??''));$bc=normx((string)($b['city']??''));if($lc!==''&&$bc!==''&&$lc!==$bc)return false;$lr=normx((string)($lead['region']??''));if($lr==='')return true;$br=splitx((string)($b['regions']??''));if(!$br)return true;foreach($br as $r)if($r===$lr||str_contains($lr,$r)||str_contains($r,$lr))return true;return false;}
function sameCityx(array $lead,array $b):bool{$lc=normx((string)($lead['city']??''));$bc=normx((string)($b['city']??''));return $lc===''||$bc===''||$lc===$bc;}
function previousx(string $lid):array{$out=[];foreach(jx(A) as $a)if((string)($a['lead_id']??'')===$lid)$out[(string)($a['branch_id']??'')]=true;return array_keys($out);}
function assignmentCountx(string $lid):int{$n=0;foreach(jx(A) as $a)if((string)($a['lead_id']??'')===$lid)$n++;return $n;}
function candidatesx(array $lead,array $exclude,bool $exact=true):array{$ex=array_fill_keys($exclude,true);$out=[];foreach(jx(B) as $b){$id=(string)($b['id']??'');if(!$id||empty($b['active'])||isset($ex[$id]))continue;if($exact?!areaExactx($lead,$b):!sameCityx($lead,$b))continue;$today=todayx($id);if($today>=quotax($b))continue;$s=statsx($id);$out[]=['b'=>$b,'score'=>$s['score'],'today'=>$today];}usort($out,function($x,$y){$d=$y['score']<=>$x['score'];return $d!==0?$d:($x['today']<=>$y['today']);});return $out;}
function eventx(string $bid,string $aid,string $lid,string $status,string $note):void{$rows=jx(EV);$rows[]=['id'=>'E'.bin2hex(random_bytes(5)),'branch_id'=>$bid,'assignment_id'=>$aid,'lead_id'=>$lid,'status'=>$status,'note'=>$note,'created_at'=>nx()];if(count($rows)>25000)$rows=array_slice($rows,-25000);sjx(EV,$rows);}
function refRewardx(string $childId,string $aid,string $lid,string $deal=''):int{$child=branchx($childId);if(!$child)return 0;$rid=(string)($child['referrer_id']??'');$rcode=(string)($child['referrer_code']??'');$ref=null;foreach(jx(B) as $x){if($rid!==''&&(string)($x['id']??'')===$rid){$ref=$x;break;}if($rcode!==''&&(string)($x['code']??'')===$rcode){$ref=$x;break;}}if(!$ref||($ref['id']??'')===$childId)return 0;$rows=jx(R);foreach($rows as $r)if(($r['assignment_id']??'')===$aid&&($r['type']??'referral_order')==='referral_order')return 0;$amount=max(0,(int)(array_key_exists('referral_reward_amount',$ref)?$ref['referral_reward_amount']:200000));if($amount<=0)return 0;$rows[]=['id'=>'R'.bin2hex(random_bytes(6)),'type'=>'referral_order','referrer_branch_id'=>$ref['id'],'referred_branch_id'=>$childId,'assignment_id'=>$aid,'lead_id'=>$lid,'amount'=>$amount,'deal_value'=>$deal,'status'=>'credited','created_at'=>nx()];sjx(R,$rows);return $amount;}

function priox(?array $lead):string{return (($lead['priority']??'normal')==='urgent')?'urgent':'normal';}
function durationx(string $priority):int{return $priority==='urgent'?7200:86400;}
function commissionx(string $priority):int{return $priority==='urgent'?40:30;}
function ensureTimerSettingsx():void{$c=jx(S);$changed=false;$defaults=['unseen_reassign_hours'=>48,'urgent_reassign_hours'=>2,'normal_reassign_hours'=>24,'commission_percent'=>30,'urgent_commission_percent'=>40,'sms_sender'=>'90008361','sms_manager_mobile'=>'09024342370','sms_api_endpoint'=>'https://edge.ippanel.com/v1/api/send','sms_enabled'=>true];foreach($defaults as $k=>$v)if(!array_key_exists($k,$c)){$c[$k]=$v;$changed=true;}if((int)($c['unseen_reassign_hours']??0)!==48){$c['unseen_reassign_hours']=48;$changed=true;}if((int)($c['urgent_reassign_hours']??0)!==2){$c['urgent_reassign_hours']=2;$changed=true;}if((int)($c['normal_reassign_hours']??0)!==24){$c['normal_reassign_hours']=24;$changed=true;}if((int)($c['commission_percent']??0)!==30){$c['commission_percent']=30;$changed=true;}if((int)($c['urgent_commission_percent']??0)!==40){$c['urgent_commission_percent']=40;$changed=true;}if($changed)sjx(S,$c);}

function smsTokenx():string{$c=cfgx();foreach(['sms_api_key','faraz_api_key','ippanel_api_key','api_key'] as $k){$v=trim((string)($c[$k]??''));if($v!=='')return $v;}foreach(['FARAZ_SMS_API_KEY','IPPANEL_API_KEY','SMS_API_KEY'] as $k){$v=getenv($k);if(is_string($v)&&trim($v)!=='')return trim($v);}return '';}
function smsRecipientx(string $m):string{$m=preg_replace('/[^0-9+]/','',$m)??'';if(str_starts_with($m,'+'))return $m;if(str_starts_with($m,'0098'))return '+'.substr($m,2);if(str_starts_with($m,'98'))return '+'.$m;if(str_starts_with($m,'09'))return '+98'.substr($m,1);return $m;}
function smsLogx(string $kind,string $mobile,string $status,string $message,string $aid='',string $lid='',string $response=''):void{$rows=jx(SMSL);$rows[]=['id'=>'SMS'.bin2hex(random_bytes(5)),'kind'=>$kind,'mobile'=>$mobile,'status'=>$status,'assignment_id'=>$aid,'lead_id'=>$lid,'message'=>$message,'response'=>mb_substr($response,0,1000),'created_at'=>nx()];if(count($rows)>5000)$rows=array_slice($rows,-5000);sjx(SMSL,$rows);}
function smsRequestx(array $payload,string $token):array{$c=cfgx();$url=trim((string)($c['sms_api_endpoint']??'https://edge.ippanel.com/v1/api/send'));$body=json_encode($payload,JSON_UNESCAPED_UNICODE);if($body===false)return [false,'json_error'];$headers=['Content-Type: application/json','Accept: application/json','Authorization: '.$token];if(function_exists('curl_init')){$ch=curl_init($url);curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>$headers,CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>8,CURLOPT_TIMEOUT=>15]);$res=(string)curl_exec($ch);$err=(string)curl_error($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$ok=$code>=200&&$code<300;if($ok&&$res!==''){$j=json_decode($res,true);if(is_array($j)&&isset($j['meta']['status'])&&$j['meta']['status']===false)$ok=false;}return [$ok,$err!==''?$err:$res];}$ctx=stream_context_create(['http'=>['method'=>'POST','header'=>implode("\r\n",$headers)."\r\n",'content'=>$body,'timeout'=>15,'ignore_errors'=>true]]);$res=@file_get_contents($url,false,$ctx);$status=$http_response_header[0]??'';$ok=is_string($res)&&preg_match('/\s2\d\d\s/',$status)===1;return [$ok,is_string($res)?$res:$status];}
function smsSendx(string $mobile,string $message,string $kind,string $aid='',string $lid='',array $patternParams=[]):bool{$c=cfgx();if(empty($c['sms_enabled']))return false;$token=smsTokenx();$to=smsRecipientx($mobile);if($token===''||$to===''){smsLogx($kind,$mobile,'not_configured',$message,$aid,$lid);return false;}$sender=trim((string)($c['sms_sender']??'90008361'));
$patternKey='';if($kind==='new_order')$patternKey=(string)($c['sms_new_order_pattern']??'');elseif($kind==='half_reminder')$patternKey=(string)($c['sms_half_reminder_pattern']??'');elseif($kind==='manager_report')$patternKey=(string)($c['sms_manager_report_pattern']??'');
if($patternKey!==''){$payload=['sending_type'=>'pattern','from_number'=>$sender,'code'=>$patternKey,'recipients'=>[$to],'params'=>$patternParams];[$ok,$res]=smsRequestx($payload,$token);if($ok){smsLogx($kind,$mobile,'sent_pattern',$message,$aid,$lid,$res);return true;}smsLogx($kind,$mobile,'pattern_failed',$message,$aid,$lid,$res);}
$payload=['sending_type'=>'webservice','from_number'=>$sender,'message'=>$message,'params'=>['recipients'=>[$to]]];[$ok,$res]=smsRequestx($payload,$token);smsLogx($kind,$mobile,$ok?'sent':'failed',$message,$aid,$lid,$res);return $ok;}
function assignmentLinkx(string $aid):string{return 'https://websaza.ir/namayandegi/?view=leads#lead-'.$aid;}
function notifyNewRowx(array &$a,bool $force=false):bool{if(!empty($a['sms_new_sent_at']))return false;$last=strtotime((string)($a['sms_new_last_attempt_at']??''))?:0;if(!$force&&$last>time()-300)return false;$a['sms_new_last_attempt_at']=nx();$branch=branchx((string)($a['branch_id']??''));$lead=leadx((string)($a['lead_id']??''));if(!$branch||!$lead)return true;$priority=(string)($a['priority']??priox($lead));$commission=(int)($a['commission_percent']??commissionx($priority));$a['commission_percent']=$commission;$kind=$priority==='urgent'?'فوری':'معمولی';$hours=$priority==='urgent'?2:24;$biz=(string)($lead['business']??$lead['name']??'مشتری');$aid=(string)($a['id']??'');$lid=(string)($a['lead_id']??'');$link=assignmentLinkx($aid);$message="وب ساز\nسفارش جدید دارید.\nنوع: {$kind}\nسهم شما از این سفارش: {$commission}٪\nمهلت تعیین تکلیف: {$hours} ساعت\n{$biz}\n{$link}";$params=['name'=>(string)($branch['name']??'نمایندگی'),'order'=>$biz,'marketer'=>(string)($branch['name']??'نمایندگی'),'total'=>$commission.'٪','url'=>$link,'commission'=>$commission.'٪','hours'=>(string)$hours,'type'=>$kind];if(smsSendx((string)($branch['mobile']??''),$message,'new_order',$aid,$lid,$params))$a['sms_new_sent_at']=nx();return true;}
function notifyHalfRowx(array &$a):bool{if(!empty($a['sms_half_sent_at']))return false;$lead=leadx((string)($a['lead_id']??''));if(!$lead)return false;$priority=(string)($a['priority']??priox($lead));$base=strtotime((string)($a['created_at']??''))?:0;if(!$base)return false;$mid=strtotime((string)($a['midpoint_at']??''))?:($base+intdiv(durationx($priority),2));$deadline=strtotime((string)($a['deadline_at']??''))?:($base+durationx($priority));$now=time();if($now<$mid||$now>=$deadline)return false;$last=strtotime((string)($a['sms_half_last_attempt_at']??''))?:0;if($last>$now-300)return false;$a['sms_half_last_attempt_at']=nx();$branch=branchx((string)($a['branch_id']??''));if(!$branch)return true;$aid=(string)($a['id']??'');$lid=(string)($a['lead_id']??'');$biz=(string)($lead['business']??$lead['name']??'مشتری');$passed=$priority==='urgent'?1:12;$remain=$priority==='urgent'?1:12;$link=assignmentLinkx($aid);$message="وب ساز\nیک سفارش باز دارید و هنوز تعیین تکلیف نشده است.\n{$passed} ساعت از مهلت گذشته و حدود {$remain} ساعت باقی مانده.\n{$biz}\nلطفاً نتیجه تماس را ثبت کنید.\n{$link}";$params=['name'=>(string)($branch['name']??'نمایندگی'),'order'=>$biz,'hours'=>(string)$remain,'url'=>$link];if(smsSendx((string)($branch['mobile']??''),$message,'half_reminder',$aid,$lid,$params))$a['sms_half_sent_at']=nx();return true;}
function managerReportx(string $lid,string $aid,string $bid,string $reason):void{$reports=jx(MR);foreach($reports as $r)if((string)($r['assignment_id']??'')===$aid)return;$lead=leadx($lid);$branch=branchx($bid);$biz=(string)($lead['business']??$lead['name']??'مشتری');$reports[]=['id'=>'MR'.bin2hex(random_bytes(5)),'lead_id'=>$lid,'assignment_id'=>$aid,'branch_id'=>$bid,'business'=>$biz,'reason'=>$reason,'created_at'=>nx(),'status'=>'open'];if(count($reports)>5000)$reports=array_slice($reports,-5000);sjx(MR,$reports);eventx($bid,$aid,$lid,'manager_review',$reason);$c=cfgx();$mobile=(string)($c['sms_manager_mobile']??'09024342370');$phone=(string)($lead['phone']??'');$message="وب ساز - گزارش مدیر\nگردش سفارش متوقف شد.\n{$biz}\n{$phone}\n{$reason}\nاین سفارش برای نفر سوم ارسال نشد.";$params=['name'=>$biz,'order'=>$biz,'marketer'=>(string)($branch['name']??'-'),'total'=>'-','reported'=>$reason,'extra'=>'ارسال به نفر سوم متوقف شد'];smsSendx($mobile,$message,'manager_report',$aid,$lid,$params);}
function normalizeTimersx(array &$rows):bool{$changed=false;foreach($rows as &$a){if(($a['current']??true)===false||($a['status']??'new')!=='new')continue;$lead=leadx((string)($a['lead_id']??''));$priority=(string)($a['priority']??'');if(!in_array($priority,['urgent','normal'],true)){$priority=priox($lead);$a['priority']=$priority;$changed=true;}$base=strtotime((string)($a['created_at']??nx()))?:time();if(empty($a['deadline_at'])){$a['deadline_at']=date('Y-m-d H:i:s',$base+durationx($priority));$a['timer_managed']=true;$changed=true;}if(empty($a['midpoint_at'])){$a['midpoint_at']=date('Y-m-d H:i:s',$base+intdiv(durationx($priority),2));$changed=true;}$commission=commissionx($priority);if((int)($a['commission_percent']??0)!==$commission){$a['commission_percent']=$commission;$changed=true;}}unset($a);return $changed;}
function dispatchTimedx(string $lid,array $exclude=[]):?array{$lead=leadx($lid);if(!$lead||isset($lead['active'])&&!$lead['active'])return null;if(assignmentCountx($lid)>=2)return null;$cand=candidatesx($lead,$exclude,true);if(!$cand)$cand=candidatesx($lead,$exclude,false);if(!$cand)return null;$b=$cand[0]['b'];$priority=priox($lead);$created=nx();$dur=durationx($priority);$new=['id'=>'A'.bin2hex(random_bytes(5)),'branch_id'=>$b['id'],'lead_id'=>$lid,'date'=>tdx(),'status'=>'new','note'=>'','followup_at'=>'','project_type'=>'','deal_value'=>'','seen_at'=>'','current'=>true,'priority'=>$priority,'commission_percent'=>commissionx($priority),'timer_managed'=>true,'midpoint_at'=>date('Y-m-d H:i:s',strtotime($created)+intdiv($dur,2)),'deadline_at'=>date('Y-m-d H:i:s',strtotime($created)+$dur),'created_at'=>$created,'updated_at'=>''];$rows=jx(A);$rows[]=$new;if(!sjx(A,$rows))return null;eventx((string)$b['id'],(string)$new['id'],$lid,'new',($priority==='urgent'?'سفارش فوری با مهلت ۲ ساعت و سهم ۴۰٪':'سفارش معمولی با مهلت ۲۴ ساعت و سهم ۳۰٪').' به نماینده ارسال شد');$rows=jx(A);foreach($rows as &$r)if((string)($r['id']??'')===(string)$new['id']){notifyNewRowx($r,true);$new=$r;break;}unset($r);sjx(A,$rows);return $new;}
function tickTimersx():array{ensureTimerSettingsx();$rows=jx(A);$changed=normalizeTimersx($rows);$expired=[];$stopped=[];$now=time();foreach($rows as &$a){if(($a['current']??true)===false||($a['status']??'new')!=='new')continue;if(notifyNewRowx($a))$changed=true;if(notifyHalfRowx($a))$changed=true;$deadline=strtotime((string)($a['deadline_at']??''));if(!$deadline||$deadline>$now)continue;$lid=(string)($a['lead_id']??'');$bid=(string)($a['branch_id']??'');$aid=(string)($a['id']??'');$priority=(string)($a['priority']??'normal');if(assignmentCountx($lid)>=2){$a['current']=false;$a['status']='no_answer';$a['manager_review']=true;$a['closed_rotation']=true;$a['updated_at']=nx();$a['timer_expired']=true;$stopped[]=['lead_id'=>$lid,'branch_id'=>$bid,'assignment_id'=>$aid,'priority'=>$priority,'reason'=>'پس از دو نوبت واگذاری هنوز سفارش تعیین تکلیف/قطعی نشده است.'];}else{$a['current']=false;$a['status']='reassigned';$a['reassigned_at']=nx();$a['updated_at']=nx();$a['timer_expired']=true;$expired[]=['lead_id'=>$lid,'branch_id'=>$bid,'assignment_id'=>$aid,'priority'=>$priority];}$changed=true;}unset($a);if($changed)sjx(A,$rows);$moved=0;foreach($expired as $x){$label=$x['priority']==='urgent'?'مهلت ۲ ساعته':'مهلت ۲۴ ساعته';eventx($x['branch_id'],$x['assignment_id'],$x['lead_id'],'reassigned',$label.' بدون ثبت نتیجه تمام شد و سفارش خودکار برای نوبت دوم منتقل شد');$new=dispatchTimedx($x['lead_id'],previousx($x['lead_id']));if($new)$moved++;else managerReportx($x['lead_id'],$x['assignment_id'],$x['branch_id'],'برای نوبت دوم نماینده واجد شرایط پیدا نشد؛ سفارش به مدیر ارجاع شد.');}foreach($stopped as $x)managerReportx($x['lead_id'],$x['assignment_id'],$x['branch_id'],$x['reason']);return ['expired'=>count($expired)+count($stopped),'moved'=>$moved,'manager_review'=>count($stopped)];}
function g2jx(int $gy,int $gm,int $gd):array{$gdm=[0,31,59,90,120,151,181,212,243,273,304,334];if($gy>1600){$jy=979;$gy-=1600;}else{$jy=0;$gy-=621;}$gy2=$gm>2?$gy+1:$gy;$days=365*$gy+intdiv($gy2+3,4)-intdiv($gy2+99,100)+intdiv($gy2+399,400)-80+$gd+$gdm[$gm-1];$jy+=33*intdiv($days,12053);$days%=12053;$jy+=4*intdiv($days,1461);$days%=1461;if($days>365){$jy+=intdiv($days-1,365);$days=($days-1)%365;}if($days<186){$jm=1+intdiv($days,31);$jd=1+$days%31;}else{$jm=7+intdiv($days-186,30);$jd=1+($days-186)%30;}return[$jy,$jm,$jd];}
