function fadtimex(string $s):string{$ts=strtotime($s);if(!$ts)return '-';[$jy,$jm,$jd]=g2jx((int)date('Y',$ts),(int)date('n',$ts),(int)date('j',$ts));$days=[0=>'یکشنبه',1=>'دوشنبه',2=>'سه‌شنبه',3=>'چهارشنبه',4=>'پنجشنبه',5=>'جمعه',6=>'شنبه'];$months=[1=>'فروردین',2=>'اردیبهشت',3=>'خرداد',4=>'تیر',5=>'مرداد',6=>'شهریور',7=>'مهر',8=>'آبان',9=>'آذر',10=>'دی',11=>'بهمن',12=>'اسفند'];return $days[(int)date('w',$ts)].' '.fdx((string)$jd).' '.$months[$jm].' '.fdx((string)$jy).'، ساعت '.fdx(date('H:i:s',$ts));}
